using namespace std;
typedef long long ll;

int main() {
    int n;
    ll z;
    scanf("%d %lld", &n, &z);
    const ll NEG = -(1LL << 60);
    // Best sum of a scored run ending here: before / inside / after the amplified segment.
    ll before = 0, inside = NEG, after = NEG, best = 0;
    for (int i = 0; i < n; i++) {
        ll x;
        scanf("%lld", &x);
        ll b = max(0LL, before + x);
        ll in = max(before + z * x, inside + z * x);
        ll af = max(inside + x, after + x);
        before = b; inside = in; after = af;
        best = max({best, before, inside, after});
    }
    printf("%lld\n", best);
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int n = (int) readLong(in);
        long z = readLong(in);
        final long NEG = -(1L << 60);
        // Best sum of a scored run ending here: before / inside / after the amplified segment.
        long before = 0, inside = NEG, after = NEG, best = 0;
        for (int i = 0; i < n; i++) {
            long x = readLong(in);
            long b = Math.max(0, before + x);
            long ins = Math.max(before + z * x, inside + z * x);
            long af = Math.max(inside + x, after + x);
            before = b; inside = ins; after = af;
            best = Math.max(best, Math.max(before, Math.max(inside, after)));
        }
        System.out.println(best);
    }

    static long readLong(DataInputStream in) throws IOException {
        int c = in.read();
        while (c != '-' && (c < '0' || c > '9')) c = in.read();
        boolean neg = c == '-';
        if (neg) c = in.read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = in.read(); }
        return neg ? -r : r;
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int64 { sc.Scan(); v, _ := strconv.ParseInt(sc.Text(), 10, 64); return v }
	n, z := int(next()), next()
	const neg = -(int64(1) << 60)
	// Best sum of a scored run ending here: before / inside / after the amplified segment.
	before, inside, after, best := int64(0), neg, neg, int64(0)
	for i := 0; i < n; i++ {
		x := next()
		before, inside, after = max(0, before+x), max(before+z*x, inside+z*x), max(inside+x, after+x)
		best = max(best, before, inside, after)
	}
	fmt.Println(best)
}
